// Reads a git diff on stdin and lists the changes that make a check easier to pass.
// Usage: git diff main..<branch> | node ../false-heal.mjs
import { readFileSync } from "node:fs";

const TEST_FILE = /(^|\/)(tests?|e2e)\/|\.(test|spec)\.[cm]?[jt]sx?$/;
const SKIP = /\b(it|test|describe)\.(skip|only|todo|fixme)\(/;
const ASSERT = /\bassert(\.\w+)?\(|\bexpect\(/;
const THRESHOLD = /(fail[_-]under|retries|timeout)\W+([\d.]+)/i;
const looser = (key, before, after) => (/fail/i.test(key) ? after < before : after > before);

const files = readFileSync(0, "utf8").split(/^diff --git /m).slice(1).map((chunk) => {
  const lines = chunk.split("\n");
  const path = lines[0].split(" b/")[1];
  const changed = lines.filter((l) => /^[+-]/.test(l) && !/^(\+\+\+|---) /.test(l));
  return { path, added: changed.filter((l) => l[0] === "+").map((l) => l.slice(1)),
    removed: changed.filter((l) => l[0] === "-").map((l) => l.slice(1)) };
});

const found = [];
for (const f of files) {
  for (const line of f.added.filter((l) => SKIP.test(l))) found.push(`${f.path}: new skip: ${line.trim()}`);
  if (TEST_FILE.test(f.path)) {
    const lost = f.removed.filter((l) => ASSERT.test(l)).length - f.added.filter((l) => ASSERT.test(l)).length;
    if (lost > 0) found.push(`${f.path}: ${lost} assertion(s) removed`);
  }
  for (const old of f.removed) {
    const [, key, before] = THRESHOLD.exec(old) ?? [];
    if (!key) continue;
    const now = f.added.map((l) => THRESHOLD.exec(l)).find((m) => m?.[1] === key);
    if (now && looser(key, Number(before), Number(now[2]))) found.push(`${f.path}: ${key} loosened ${before} -> ${now[2]}`);
  }
}
console.log(found.length ? `FALSE HEAL\n  ${found.join("\n  ")}` : "no false heals found");
process.exitCode = found.length ? 1 : 0;
